def canon(cells, refl=True):
 pts=[(y-min(y for y,x in cells),x-min(x for y,x in cells)) for y,x in cells]
 forms=[]
 for k in range(8 if refl else 4):
  ps=[]
  for y,x in pts:
   if k>=4: x=-x
   for _ in range(k%4): y,x=x,-y
   ps.append((y,x))
  my=min(y for y,x in ps);mx=min(x for y,x in ps)
  forms.append(tuple(sorted((y-my,x-mx) for y,x in ps)))
 return min(forms)
